import React, { useState } from 'react';
import type { PageId } from '../types/lifex';
import { ArrowUpRight, Box, CarFront } from 'lucide-react';
import { COMPONENTS } from './componentKnowledge';
import { runSelectionFlight } from '../utils/selectionMotion';

interface Props {
  onNavigate: (page: PageId) => void;
  onSelectComponent: (index: number) => void;
}

const assemblyImage =
  'data:image/jpeg;base64,';

const componentImages = [
  'data:image/jpeg;base64,',
  'data:image/jpeg;base64,',
  'data:image/jpeg;base64,',
  'data:image/jpeg;base64,',
  'data:image/jpeg;base64,',
  'data:image/jpeg;base64,',
];

export const RearSuspensionSubsystemsPage: React.FC<Props> = ({
  onSelectComponent,
}) => {
  const components = COMPONENTS.slice(0, 6);
  const [selectionBusy, setSelectionBusy] = useState(false);
  const chooseComponent = (index: number, name: string, source: HTMLButtonElement) => {
    if (selectionBusy) return; setSelectionBusy(true);
    runSelectionFlight(source, { title: name, subtitle: 'COMPONENT SELECTED', imageSrc: '/rebound-bumper-real.webp', targetLabel: 'COMPONENT WORKSPACE', target: { left: 28, top: Math.round(window.innerHeight * .43), width: 246, height: 76 }, duration: 920, onComplete: () => onSelectComponent(index) });
  };

  return (
    <main className="min-h-[calc(100vh-58px)] overflow-x-hidden bg-[#020c15] px-4 py-5 text-slate-100 sm:px-6 lg:px-7 lifex-page-enter">
      <div className="mx-auto grid max-w-[1700px] grid-cols-1 gap-4 lg:grid-cols-[330px_minmax(0,1fr)] xl:grid-cols-[350px_minmax(0,1fr)]">
        <aside className="relative isolate flex min-h-[390px] flex-col overflow-hidden rounded-[26px] border border-cyan-500/55 bg-gradient-to-b from-[#062536] via-[#041925] to-[#03111c] p-5 shadow-[0_18px_60px_rgba(0,0,0,.24)] lg:min-h-[650px]">
          <div className="pointer-events-none absolute -bottom-10 -left-12 -right-12 h-44 rounded-[50%] border-t border-cyan-400/20 bg-[radial-gradient(ellipse_at_bottom,rgba(0,190,220,.20),transparent_68%)]" />
          <div className="relative mt-2 rounded-[22px] border border-cyan-400/80 bg-[#03131f] p-2 shadow-[0_0_28px_rgba(0,210,235,.16),inset_0_0_22px_rgba(0,190,220,.08)]">
            <div className="pointer-events-none absolute left-2 top-2 h-7 w-7 rounded-tl-xl border-l-[3px] border-t-[3px] border-cyan-300" />
            <div className="pointer-events-none absolute bottom-2 right-2 h-7 w-7 rounded-br-xl border-b-[3px] border-r-[3px] border-cyan-300" />
            <img
              src={assemblyImage}
              alt="Rear suspension assembly"
              className="h-[230px] w-full rounded-[16px] object-contain sm:h-[270px] lg:h-[260px] xl:h-[285px]"
            />
          </div>

          <div className="relative mt-6 inline-flex min-h-[72px] items-center gap-3 rounded-2xl border border-cyan-400/70 bg-gradient-to-r from-[#075064]/90 via-[#063044]/90 to-[#071a2b]/95 px-4 py-3 shadow-[0_0_26px_rgba(0,190,220,.12)]">
            <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-cyan-400/10 text-cyan-300">
              <CarFront className="h-6 w-6" />
            </span>
            <h1 className="text-xl font-bold tracking-tight text-white sm:text-2xl">
              Rear Suspension
            </h1>
          </div>
        </aside>

        <section className="min-w-0 rounded-[26px] border border-cyan-900/70 bg-gradient-to-br from-[#041724]/95 to-[#020e18]/95 p-4 shadow-[0_18px_60px_rgba(0,0,0,.20)] sm:p-5 lg:p-6">
          <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <span className="flex h-10 w-10 items-center justify-center rounded-xl border border-cyan-500/45 bg-cyan-500/10 text-cyan-300 shadow-[0_0_18px_rgba(0,200,225,.10)]">
                <Box className="h-6 w-6" />
              </span>
              <h2 className="text-xl font-bold tracking-tight text-white sm:text-2xl">
                Components of Rear Suspension
              </h2>
            </div>
            <span className="rounded-full border border-cyan-600/60 bg-cyan-950/50 px-4 py-2 text-[10px] font-bold tracking-wide text-cyan-300 sm:text-xs">
              06 COMPONENTS
            </span>
          </div>

          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-3">
            {components.map((part, index) => (
              <button
                key={part.id}
                type="button"
                onClick={(event) => chooseComponent(index, part.name, event.currentTarget)} disabled={selectionBusy}
                aria-label={`Open ${part.name} component workspace`}
                className="group relative flex min-w-0 flex-col overflow-hidden rounded-[20px] border border-cyan-800/70 bg-gradient-to-b from-[#082131] via-[#061a28] to-[#04131f] text-left shadow-[0_10px_28px_rgba(0,0,0,.18)] transition-all duration-300 hover:-translate-y-1 hover:border-cyan-400/90 hover:shadow-[0_16px_38px_rgba(0,190,220,.15)] focus:outline-none focus:ring-2 focus:ring-cyan-300/80"
              >
                <div className="relative flex h-[180px] items-center justify-center overflow-hidden bg-[radial-gradient(ellipse_at_center,rgba(15,100,125,.22),rgba(2,14,23,.08)_72%)] sm:h-[195px]">
                  <div className="pointer-events-none absolute inset-0 opacity-50 [background-image:radial-gradient(rgba(53,211,230,.25)_1px,transparent_1px)] [background-size:30px_30px]" />
                  <img
                    src={componentImages[index]}
                    alt={part.name}
                    loading="lazy"
                    className="relative z-10 h-full w-full object-contain p-3 transition-transform duration-500 group-hover:scale-[1.05]"
                  />
                  <span className="pointer-events-none absolute bottom-0 left-6 right-6 h-px bg-gradient-to-r from-transparent via-cyan-500/55 to-transparent" />
                </div>

                <div className="flex flex-1 flex-col border-t border-cyan-900/65 bg-[#041521]/90 px-4 py-3.5">
                  <h3 className="text-base font-bold text-white transition-colors group-hover:text-cyan-200 sm:text-lg">
                    {part.name}
                  </h3>
                  <div className="mt-3 flex items-center justify-between gap-2 border-t border-cyan-950/90 pt-3">
                    <span className="text-[10px] font-bold uppercase tracking-wide text-cyan-300 sm:text-[11px]">
                      Open Component Workspace
                    </span>
                    <ArrowUpRight className="h-4 w-4 shrink-0 text-cyan-300 transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5" />
                  </div>
                </div>
              </button>
            ))}
          </div>
        </section>
      </div>
    </main>
  );
};
